package org.unicog.numberrace.ui;
import java.awt.*;import javax.swing.*;import org.unicog.numberrace.data.Student;
public class PlayerCellRenderer extends DefaultListCellRenderer {private boolean selected,focus;private String initials="";private ImageIcon avatar;public Component getListCellRendererComponent(JList list,Object value,int index,boolean selected,boolean focus){super.getListCellRendererComponent(list,value,index,selected,focus);this.selected=selected;this.focus=focus;setOpaque(false);setForeground(GameTheme.INK);setBorder(BorderFactory.createEmptyBorder(4,58,4,24));if(value instanceof Student){Student s=(Student)value;avatar=PlayerAvatars.icon(PlayerAvatars.get(s),42);String first=s.getFirstName(),last=s.getLastName();setText(first+" "+last);initials=first.isEmpty()?"?":first.substring(0,1).toUpperCase();}else {initials="?";avatar=null;}return this;}protected void paintComponent(Graphics g){Graphics2D p=GameTheme.graphics(g);int h=getHeight(),w=getWidth();GameTheme.surface(p,w,h,selected?new Color(255,250,190):new Color(248,252,255),selected?new Color(255,229,111):new Color(218,234,249),22);int d=Math.min(42,h-12);p.setColor(new Color(30,128,196));p.fillOval(9,(h-d)/2,d,d);p.setColor(Color.WHITE);p.setFont(getFont().deriveFont(Font.BOLD,20f));p.drawString(initials,9+(d-p.getFontMetrics().stringWidth(initials))/2,(h+p.getFontMetrics().getAscent()-p.getFontMetrics().getDescent())/2);if(avatar!=null)p.drawImage(avatar.getImage(),9,(h-d)/2,d,d,null);if(selected||focus){p.setColor(new Color(27,120,56));p.setStroke(new BasicStroke(2));p.drawRoundRect(2,1,w-5,h-7,22,22);}if(selected){p.drawLine(w-21,h/2,w-16,h/2+5);p.drawLine(w-16,h/2+5,w-8,h/2-5);}p.dispose();super.paintComponent(g);}}